interface LocalSliderProps {
  min?: number;
  max?: number;
  step?: number;
  value: number | [number, number];
  onChange: (value: number | [number, number]) => void;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  theme?: 'default' | 'brand-navy' | 'brand-teal';
}

const LocalSlider = ({
  min = 0,
  max = 100,
  step = 1,
  value,
  onChange,
  disabled = false,
  size = 'md',
  theme = 'default'
}: LocalSliderProps) => {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const isRange = Array.isArray(value);

  const handlePointerDown = (index: 0 | 1) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    const el = e.currentTarget;
    el.setPointerCapture(e.pointerId);

    const handlePointerMove = (moveEvent: PointerEvent) => {
      if (!trackRef.current) return;
      const rect = trackRef.current.getBoundingClientRect();
      const percentage = Math.max(0, Math.min(1, (moveEvent.clientX - rect.left) / rect.width));
      const rawVal = min + percentage * (max - min);
      const steppedVal = Math.round(rawVal / step) * step;
      const clampedVal = Math.max(min, Math.min(max, steppedVal));

      if (isRange) {
        const newValue = [...value] as [number, number];
        if (index === 0) {
          newValue[0] = Math.min(clampedVal, value[1] - step);
        } else {
          newValue[1] = Math.max(clampedVal, value[0] + step);
        }
        onChange(newValue);
      } else {
        onChange(clampedVal);
      }
    };

    const handlePointerUp = (upEvent: PointerEvent) => {
      el.releasePointerCapture(upEvent.pointerId);
      el.removeEventListener('pointermove', handlePointerMove);
      el.removeEventListener('pointerup', handlePointerUp);
    };

    el.addEventListener('pointermove', handlePointerMove);
    el.addEventListener('pointerup', handlePointerUp);
  };

  const handleKeyDown = (index: 0 | 1) => (e: React.KeyboardEvent) => {
    if (disabled) return;
    let currentVal = isRange ? value[index] : (value as number);
    let nextVal = currentVal;

    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
      nextVal = Math.min(max, currentVal + step);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
      nextVal = Math.max(min, currentVal - step);
      e.preventDefault();
    } else if (e.key === 'Home') {
      nextVal = min;
      e.preventDefault();
    } else if (e.key === 'End') {
      nextVal = max;
      e.preventDefault();
    }

    if (nextVal !== currentVal) {
      if (isRange) {
        const newValue = [...value] as [number, number];
        if (index === 0) {
          newValue[0] = Math.min(nextVal, value[1] - step);
        } else {
          newValue[1] = Math.max(nextVal, value[0] + step);
        }
        onChange(newValue);
      } else {
        onChange(nextVal);
      }
    }
  };

  const val1 = isRange ? value[0] : (value as number);
  const val2 = isRange ? value[1] : max;
  const leftPercent = ((val1 - min) / (max - min)) * 100;
  const rightPercent = ((val2 - min) / (max - min)) * 100;

  const sizeStyles = {
    sm: { track: 'h-1', thumb: 'h-4 w-4 -mt-1.5' },
    md: { track: 'h-1.5', thumb: 'h-5 w-5 -mt-1.5' },
    lg: { track: 'h-2.5', thumb: 'h-6 w-6 -mt-2' }
  }[size];

  const themeStyles = {
    default: { fill: 'bg-primary dark:bg-slate-400', thumb: 'border-primary dark:border-slate-400 bg-card' },
    'brand-navy': { fill: 'bg-primary dark:bg-primary-500', thumb: 'border-primary dark:border-primary-500 bg-card' },
    'brand-teal': { fill: 'bg-secondary-500', thumb: 'border-secondary-500 bg-card' }
  }[theme];

  return (
    <div 
      ref={trackRef}
      className={`relative w-full rounded-full bg-muted dark:bg-slate-800 ${sizeStyles.track} ${disabled ? 'opacity-40 cursor-not-allowed' : 'cursor-pointer'}`}
    >
      <div 
        className={`absolute rounded-full h-full ${themeStyles.fill}`}
        style={{
          left: `${isRange ? leftPercent : 0}%`,
          right: `${100 - (isRange ? rightPercent : leftPercent)}%`
        }}
      />
      <div 
        role="slider"
        aria-valuemin={min}
        aria-valuemax={isRange ? val2 : max}
        aria-valuenow={val1}
        aria-disabled={disabled}
        tabIndex={disabled ? -1 : 0}
        onPointerDown={handlePointerDown(0)}
        onKeyDown={handleKeyDown(0)}
        className={`absolute rounded-full border-2 transition-shadow shadow-xs focus-visible:ring-2 focus-visible:ring-primary dark:focus-visible:ring-slate-400 outline-none ${sizeStyles.thumb} ${themeStyles.thumb}`}
        style={{ left: `calc(${leftPercent}% - ${size === 'sm' ? '8px' : size === 'md' ? '10px' : '12px'})` }}
      />
      {isRange && (
        <div 
          role="slider"
          aria-valuemin={val1}
          aria-valuemax={max}
          aria-valuenow={val2}
          aria-disabled={disabled}
          tabIndex={disabled ? -1 : 0}
          onPointerDown={handlePointerDown(1)}
          onKeyDown={handleKeyDown(1)}
          className={`absolute rounded-full border-2 transition-shadow shadow-xs focus-visible:ring-2 focus-visible:ring-primary dark:focus-visible:ring-slate-400 outline-none ${sizeStyles.thumb} ${themeStyles.thumb}`}
          style={{ left: `calc(${rightPercent}% - ${size === 'sm' ? '8px' : size === 'md' ? '10px' : '12px'})` }}
        />
      )}
    </div>
  );
};

