  const addSonnerToast = (
    title: string,
    description?: string,
    type: 'default' | 'success' | 'error' | 'warning' | 'info' = 'default',
    duration = 4000,
    actionLabel?: string
  ) => {
    const id = Math.random().toString(36).substring(2, 9);
    const newToast: SonnerToast = { id, title, description, type, duration, actionLabel };
    setSonnerToasts(prev => [...prev, newToast]);

    if (duration > 0) {
      setTimeout(() => {
        setSonnerToasts(prev => prev.filter(t => t.id !== id));
      }, duration);
    }
  };









