    code += "  size?: 'sm' | 'md' | 'lg';\n";
    code += "  pressed?: boolean;\n";
    code += "  onPressedChange?: (pressed: boolean) => void;\n";
    code += "  disabled?: boolean;\n";
    code += "  children: React.ReactNode;\n";
    code += "  'aria-label'?: string;\n";
    code += "}\n\n";
    code += "export function Toggle({\n";
    code += "  variant = '" + playToggleVariant + "',\n";
    code += "  size = '" + playToggleSize + "',\n";
