      `            <div className="text-xs font-bold text-foreground">Transaction Update</div>\n` +
      `            <p className="text-[11px] leading-relaxed text-muted-foreground">Ledger dispatch was executed and logged successfully.</p>\n` +
      `          </div>\n` +
      `          <button onClick={onClose} className="p-1 hover:bg-muted text-muted-foreground hover:text-foreground rounded-lg transition cursor-pointer shrink-0">\n` +
      `            <X size={13} />\n` +
      `          </button>\n` +
      `        </motion.div>\n` +
      `      )}\n` +
      `    </AnimatePresence>\n` +
      `  )\n` +
      `}`
