              e.preventDefault();
              const menuWidth = 176;
              const menuHeight = 160;
              
              let x = e.clientX;
              let y = e.clientY;
              
              if (window.innerWidth - x < menuWidth) {
                x -= menuWidth;
              }
              if (window.innerHeight - y < menuHeight) {
                y -= menuHeight;
              }
              
              setPlayContextMenuPosition({ x, y });
              setPlayContextMenuOpen(true);
